def solve_placement(go,O,out_objs=None):
    O=np.array(O)
    oc={p:O[p] for p in [(r,c) for r in range(O.shape[0]) for c in range(O.shape[1]) if O[r,c]!=O[0,0]]}
    # backtracking: assign each object a translation; allow overlaps only between same-color
    n=len(go)
    sols=[]
    def bt(i, covered, deltas):
        if i==n:
            if covered==set(oc): sols.append(list(deltas)); return
        o=go[i]
        for dr in range(-len(O),len(O)):
            for dc in range(-len(O[0]),len(O[0])):
                pl=set((p[0]+dr,p[1]+dc) for p in o['cells'])
                conflict=False
                if pl&covered:
                    other=covered&pl
                    if {O[p] for p in other}-{oc.get(p) for p in other}:
                        continue  # overlapping different colors -> conflict; allow only if same colors
                    # same colors overlap -> fine (merge)
                ok=True
                for p in pl:
                    if p not in oc and oc.get(p)!=o['color']: ok=False; break
                if not ok: continue
                newc=covered|pl
                if newc<=set(oc):
                    bt(i+1,newc,deltas+[(dr,dc)])
    bt(0,set(),[])
    return sols

