# Absorb: attach each single pixel to the orthogonally/diagonally adjacent multi-cell comp, keeping its cell (recolored).
def absorb(I):
    I=np.array(I); bg=int(I[0,0])
    cs=comps2(I,bg)
    objs=[]; singles=[]
    for c,s in cs:
        if len(s)>1:
            objs.append({'color':int(c),'cells':set(s)})
        else:
            q=next(iter(s)); singles.append((int(c),(q[0],q[1])))
    for c,(r,qc) in singles:
        # attach to nearest obj by min manhattan; if adjacent (dist 1), prefer adjacency
        best=None
        for i,o in enumerate(objs):
            d=min(abs(r-x)+abs(qc-y) for x,y in o['cells'])
            adj=d==1
            key=(d, not adj, i)
            if best is None or key<best[0]: best=(key,i)
        i=best[1]
        objs[i]['cells'].add((r,qc))
    return objs,bg

