    ocells={(r,c):O[r][c] for r in range(O.shape[0]) for c in range(O.shape[1]) if O[r][c]!=bg}
    n=len(objs)
    sols=[]
    def bt(i,covered,deltas):
        if i==n:
            if covered==set(ocells): sols.append(list(deltas)); return
        o=objs[i]
        H,W=O.shape
        for dr in range(-H,H):
            for dc in range(-W,W):
