                if not pl and False: continue
                # allow overlap only between same-color cells; new cells must be target cells with matching color
                ok=True
                for p in pl:
                    if p not in ocells or ocells[p]!=o['color']: ok=False; break
                if not ok: continue
                bt(i+1,covered|pl,deltas+[(dr,dc)])
    bt(0,set(),[])
    print('demo8 solutions:',len(sols),sols[:3])
    return sols
