    OH=len(O); OW=len(O[0]); bg=int(I[0][0])
    bi=f4connectivity(I); bigs=[b for b in bi if len(b['cells'])>1]; sgls=[s for s in bi if len(s['cells'])==1]
    objs=[]
    for b in bigs:
        r0=min(q[0] for q in b['cells']); c0=min(q[1] for q in b['cells'])
        objs.append({'color':b['color'],'base':frozenset((p[0]-r0,p[1]-c0) for p in b['cells']),'added':set()})
    for p in sgls:
        kk=min(range(len(objs)), key=lambda kk: min(abs(p[0]-q[0])+abs(p[1]-q[1]) for q in objs[kk]['base']))
        ho=objs[kk]; r0=min(q[0] for q in ho['base']); c0=min(q[1] for q in ho['base'])
        objs[kk]['added'].add((p[0]-r0,p[1]-c0,ho['color'],kk))
    comps_=[]
    for o in objs:
        offs={(a,b) for a,b,_ in o['added']}
        tot=o['base']|offs
        h=max(x for x,y in tot)+1; w=max(y for x,y in tot)+1
        comps_.append({'color':o['color'],'offs':tot,'h':h,'w':w})
    target={(r,c) for r in range(OH) for c in range(OW) if O[r][c]!=bg}
    sols=[]
    def bt(k,used,grid,pos):
        nonlocal sols
        if k==len(comps_):
            if {(r,c) for r in range(OH) for c in range(OW) if grid[r][c]!=bg}==target: sols.append([list(row) for row in grid]); return
        o=comps_[k]
        for rr in range(OH-o['h']+1):
            for cc in range(OW-o['w']+1):
                sh=set((rr+a,cc+b) for a,b in o['offs'])
                if sh&used or any(not(0<=y<OH and 0<=x<OW) for y,x in sh): continue
                g=[list(r) for r in grid]
                for y,x in sh: g[y][x]=o['color']
                bt(k+1,used|sh,g,pos+[(rr,cc)])
    bt(0,set(),[[bg]*OW for _ in range(OH)],[])
    exact=sum(1 for g in sols if all(g[r][c]==O[r][c] for r in range(OH) for c in range(OW)))
    print(n,'nsol',len(sols),'exact',exact)
    return exact==len(sols)
