def solve_single(I,O):
    ci=comps(I); bg=I[0][0]
    objs=[b for b in ci if len(b['cells'])>1]
    sgls=[s for s in ci if len(s['cells'])==1]
    # attach each stray to orthogonally adjacent object (any color? use touching object)
    added={i:set() for i in range(len(objs))}
    for s in sgls:
        sr,sc=s['cells'][0]
        host=None
        for i,o in enumerate(objs):
            for q in o['cells']:
                if abs(q[0]-sr)+abs(q[1]-sc)==1: host=i;break
            if host is not None: break
        if host is None:
            # fallback: nearest by manhattan
            host=min(range(len(objs)), key=lambda i: min(abs(sr-q[0])+abs(sc-q[1]) for q in objs[i]['cells']))
        ho=objs[host]
        bboxr=min(q[0] for q in ho['cells']); bboxc=min(q[1] for q in ho['cells'])
        added[host].add((sr-bboxr,sc-bboxc))
    newobjs=[]
    for i,b in enumerate(objs):
        r0=min(q[0] for q in b['cells']); c0=min(q[1] for q in b['cells'])
        tot=set((q[0]-r0,q[1]-c0) for q in b['cells'])|added[i]
        h=max(r for r,c in tot)+1; w=max(c for r,c in tot)+1
        newobjs.append({'color':b['color'],'tot':tot,'h':h,'w':w})
    Oh=len(O); Ow=len(O[0]); Obg=O[0][0]
    order=sorted(range(len(newobjs)), key=lambda i:-len(newobjs[i]['tot']))
    used=set(); g=[[Obg]*Ow for _ in range(Oh)]
    for i in order:
        o=newobjs[i]; t=o['tot']; h=o['h']; w=o['w']
        found=False
        for rr in range(Oh-h+1):
            for cc in range(Ow-w+1):
                sh={(rr+a,cc+b) for a,b in t}
                if not (sh&used):
                    used|=sh
                    for y,x in sh: g[y][x]=o['color']
                    found=True;break
            if found:break
        if not found: print('UNPLACABLE',i)
    return g==[[O[r][c] for c in range(Ow)] for r in range(Oh)], g

